L19_1.m_fTalkTime = 0.03
L20_1 = "\227\129\157\227\129\151\227\129\166\227\130\172\227\131\179\227\131\136\227\131\172\227\131\131\227\131\136\227\129\167\227\129\175\231\155\184\230\137\139\227\129\174\229\145\189\227\130\146\229\165\170\227\129\134\227\129\147\227\129\168\227\129\175\232\168\177\227\129\149\227\130\140\227\129\166\227\129\132\227\129\190\227\129\155\227\130\147\227\128\130\227\129\157\227\129\134\227\129\153\227\130\139\227\129\168\227\130\128\227\129\151\227\130\141\232\178\160\227\129\145\227\129\166\227\129\151\227\129\190\227\129\132\227\129\190\227\129\153\227\128\130"
