L19_1.m_Talk_ENG = L20_1
L20_1 = "\229\156\168\232\129\150\233\142\167\230\152\175\228\184\141\229\143\175\228\187\165\229\165\170\232\181\176\229\176\141\230\150\185\230\128\167\229\145\189\231\154\132\239\188\140\233\130\163\233\186\188\229\129\154\229\143\141\232\128\140\230\156\131\232\188\184\227\128\130"
L19_1.m_Talk_TWN = L20_1
L20_1 = "\224\185\129\224\184\165\224\184\176\224\185\131\224\184\153 \224\184\129\224\185\138\224\184\173\224\184\149\224\185\128\224\184\165\224\185\135\224\184\151  \224\185\128\224\184\163\224\184\178\224\184\150\224\184\185\224\184\129\224\184\171\224\185\137\224\184\178\224\184\161\224\185\132\224\184\161\224\185\136\224\185\131\224\184\171\224\185\137\224\184\134\224\185\136\224\184\178\224\184\156\224\184\185\224\185\137\224\184\173\224\184\183\224\185\136\224\184\153 \224\184\153\224\184\177\224\185\136\224\184\153\224\184\153\224\184\179\224\185\132\224\184\155\224\184\170\224\184\185\224\185\136\224\184\132\224\184\167\224\184\178\224\184\161\224\184\158\224\185\136\224\184\178\224\184\162\224\185\129\224\184\158\224\185\137\224\185\128\224\184\151\224\185\136\224\184\178\224\184\153\224\184\177\224\185\137\224\184\153"
