L19_1.m_Talk_VTN = L20_1
L20_1 = "\229\156\168\229\156\163\233\147\160\230\152\175\228\184\141\229\143\175\228\187\165\229\164\186\232\181\176\229\175\185\230\150\185\230\128\167\229\145\189\231\154\132\239\188\140\233\130\163\228\185\136\229\129\154\229\143\141\232\128\140\228\188\154\232\190\147\227\128\130"
